const root = $input.item.json;
const body = root.body && typeof root.body === 'object' ? root.body : root;
const message = body.message ?? '';
const filters = body.filters ?? {};
const places = Array.isArray(body.places) ? body.places : [];
const kw = filters.keyword ?? '맛집';
const radiusM = body.radiusMeters ?? 2500;
const searchQuery = body.searchQuery ?? '';
const lines = places.map((p, i) => {
  const dist = p.distanceMeters != null ? Math.round(p.distanceMeters) + 'm' : '거리미상';
  const price = p.priceKrw != null ? Number(p.priceKrw).toLocaleString() + '원(예상·데모)' : '가격미상';
  return (i + 1) + '. ' + p.title + '\n   분류: ' + p.category + '\n   주소: ' + p.roadAddress + '\n   내 위치까지: ' + dist + '\n   예상가: ' + price;
});
const system = '너는 한국어 맛집·카페 도우미이다. 반드시 아래 "검색된 장소 목록"만 근거로 답한다. 목록에 없는 업소 이름·주소·가격을 지어내지 마라. 사용자 질문 의도(예: 내 위치 주변 카페)에 맞게 친절하고 간결하게 답하고, 각 장소마다 이름·주소·거리·예상가(데모)를 읽기 쉽게 정리해라.';
const user = '사용자 질문: ' + message + '\n\n파싱된 키워드: ' + kw + '\n지역 검색어(서버): ' + searchQuery + '\n주변 반경(대략): ' + (Math.round(radiusM / 10) / 100) + 'km\n\n검색된 장소 목록:\n' + (lines.length ? lines.join('\n\n') : '(목록 없음)');
return { json: { system, user } };

const j = $input.item.json;
const reply = (j.message && j.message.content) ? j.message.content : (j.content || j.text || '');
return { json: { reply: String(reply).trim() || '응답을 만들지 못했습니다.' } };
